enum ExactNominalSelection {
    Found(
        brokk_bifrost_core::analyzer::model::CodeUnit,
        brokk_bifrost_core::analyzer::model::Range,
        git2::Oid,
    ),
    Unknown,
    Stopped,
}

fn open_nominal_proof_operation<'a>(
    workspace: &'a brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    cancellation: &brokk_bifrost_core::cancellation::CancellationToken,
) -> Option<
    brokk_bifrost_analysis::analyzer::store::resolution_operation::SelectedResolutionOperation<
        'a,
        'a,
    >,
> {
    let factory = crate::analyzer::rust::native_points::RustDefinitionOperationFactory::new(
        workspace.analyzer(),
        cancellation,
    )?;
    match factory.open(cancellation).ok()? {
        brokk_bifrost_analysis::analyzer::store::resolution_operation::SelectedResolutionOperationOpenOutcome::Ready(operation) => Some(*operation),
        _ => None,
    }
}

/// Resolve one structured nominal site through the selected Rust operation.
/// The range is a second, bounded declaration identity check, not a name
/// search in the declaring file.
fn resolve_exact_nominal_site(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    file: &brokk_bifrost_core::analyzer::model::ProjectFile,
    source_tree: (&str, &tree_sitter::Tree),
    annotation: Node<'_>,
    cancellation: &brokk_bifrost_core::cancellation::CancellationToken,
    charge: &mut impl FnMut(usize) -> Result<(), SemanticProviderError>,
    operation: &mut brokk_bifrost_analysis::analyzer::store::resolution_operation::SelectedResolutionOperation<'_, '_>,
) -> Result<ExactNominalSelection, SemanticProviderError> {
    let (source, tree) = source_tree;
    use brokk_bifrost_analysis::analyzer::languages::{BoundedReceiverQuery, LanguageSupport};
    use brokk_bifrost_analysis::analyzer::usages::get_definition::DefinitionLookupStatus;
    use brokk_bifrost_core::analyzer::usages::receiver_analysis::ReceiverAnalysisBudget;
    use brokk_bifrost_core::analyzer::usages::reference_site::{
        SourceLocationRequest, resolve_reference_site,
    };
    use brokk_bifrost_core::analyzer::usages::resolution_session::BoundedResolution;
    if !matches!(annotation.kind(), "type_identifier" | "scoped_identifier") {
        return Ok(ExactNominalSelection::Unknown);
    }
    // The location API selects one reference token. The surrounding AST
    // supplies its qualification and namespace to the selected resolver.
    let reference = annotation.child_by_field_name("name").unwrap_or(annotation);
    let site = match resolve_reference_site(
        &SourceLocationRequest {
            file: file.clone(),
            line: None,
            column: None,
            start_byte: Some(reference.start_byte()),
            end_byte: Some(reference.end_byte()),
        },
        source,
        Some(tree.root_node()),
    ) {
        Ok(site) => site,
        Err(_) => return Ok(ExactNominalSelection::Unknown),
    };
    let budget = ReceiverAnalysisBudget::default();
    // One native point resolution. Its own work is observed through the
    // operation; the semantic budget is not an allowance for it.
    charge(1)?;
    let (resolution, receipt) =
        brokk_bifrost_analysis::analyzer::i_analyzer::QueryReadReceipt::capture(
            workspace.analyzer(),
            || {
                crate::analyzer::rust::native_points::resolve_rust_definition_in_operation(
                    BoundedReceiverQuery {
                        analyzer: workspace.analyzer(),
                        file,
                        source,
                        tree: Some(tree),
                        site: &site,
                        budget,
                        cancellation: Some(cancellation),
                    },
                    operation,
                )
            },
        );
    receipt.replay(workspace.analyzer());
    let resolved = match resolution {
        BoundedResolution::Complete { value, .. } => value,
        BoundedResolution::Exceeded { .. }
        | BoundedResolution::Unavailable { .. }
        | BoundedResolution::Cancelled { .. } => {
            return Ok(ExactNominalSelection::Stopped);
        }
    };
    if resolved.status != DefinitionLookupStatus::Resolved
        || !resolved.diagnostics.is_empty()
        || !resolved.modeled_definitions.is_empty()
    {
        return Ok(ExactNominalSelection::Unknown);
    }
    let [declaration] = resolved.definitions.as_slice() else {
        return Ok(ExactNominalSelection::Unknown);
    };
    charge(2)?;
    // The range projection selects one blob. Capture that read separately so
    // the later source snapshot must agree with the blob that supplied range.
    let (ranges, reads) = brokk_bifrost_analysis::analyzer::i_analyzer::capture_query_reads(
        workspace.analyzer(),
        || {
            crate::analyzer::rust::RustSupport.declaration_ranges_limited(
                workspace.analyzer(),
                declaration,
                2,
            )
        },
    );
    let Some(ranges) = ranges else {
        return Ok(ExactNominalSelection::Unknown);
    };
    if !ranges.complete {
        return Ok(ExactNominalSelection::Stopped);
    }
    let [range] = ranges.rows.as_slice() else {
        return Ok(ExactNominalSelection::Unknown);
    };
    let path = brokk_bifrost_analysis::path_utils::rel_path_string(declaration.source());
    let mut selected_blob = None;
    for key in reads.unordered_keys() {
        if let brokk_bifrost_analysis::analyzer::read_ledger::ReadKey::File {
            language: brokk_bifrost_core::analyzer::model::Language::Rust,
            rel_path,
            blob,
            ..
        } = key
            && rel_path.as_ref() == path
            && selected_blob
                .replace(blob)
                .is_some_and(|prior| prior != blob)
        {
            workspace.analyzer().record_query_incomplete(
                brokk_bifrost_analysis::analyzer::QueryReadIncomplete::SemanticEvidenceUnavailable(
                    "selected Rust nominal range read more than one source generation".into(),
                ),
            );
            return Ok(ExactNominalSelection::Unknown);
        }
    }
    let Some(blob) = selected_blob else {
        workspace.analyzer().record_query_incomplete(
            brokk_bifrost_analysis::analyzer::QueryReadIncomplete::SemanticEvidenceUnavailable(
                "selected Rust nominal range has no source generation".into(),
            ),
        );
        return Ok(ExactNominalSelection::Unknown);
    };
    Ok(ExactNominalSelection::Found(
        declaration.clone(),
        *range,
        blob,
    ))
}

/// Refuse a declaration proof when its selected range and later atomic source
/// snapshot came from different blob generations.
fn selected_nominal_source_matches_range(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    source: &str,
    selected_blob: git2::Oid,
) -> bool {
    if git2::Oid::hash_object(git2::ObjectType::Blob, source.as_bytes()) == Ok(selected_blob) {
        return true;
    }
    workspace.analyzer().record_query_incomplete(
        brokk_bifrost_analysis::analyzer::QueryReadIncomplete::SemanticEvidenceUnavailable(
            "selected Rust nominal declaration source changed after range selection".into(),
        ),
    );
    false
}

/// Version of the query-time Drop inventory proof protocol.
pub const RUST_DROP_INVENTORY_PROOF_VERSION: u32 = 1;

// Selection is its own recorded answer: another target can gain this source
// without changing any rows in the former owner's Drop inventory.
fn selected_drop_subject(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    snapshots: &brokk_bifrost_analysis::analyzer::store::WorkspaceSnapshots,
    rel_path: &str,
    blob: &git2::Oid,
    start_byte: usize,
    end_byte: usize,
) -> brokk_bifrost_analysis::analyzer::store::Result<
    std::result::Result<
        brokk_bifrost_analysis::analyzer::store::rust_drop_inventory::RustDropInventorySubject,
        brokk_bifrost_analysis::analyzer::store::rust_drop_inventory::RustDropInventoryReason,
    >,
> {
    use brokk_bifrost_analysis::analyzer::read_ledger::{LookupKind, LookupQuestion, ReadKey};
    let cpu = crate::profiling::enabled().then(crate::profiling::thread_cpu_time);
    let selection = workspace
        .store()
        .expect("selected store")
        .rust_drop_inventory_subject(snapshots, rel_path, blob, start_byte, end_byte)?;
    if let Some(cpu) = cpu {
        crate::profiling::note(format!(
            "inert_drop.subject_read calls=1 cpu_ns={}",
            crate::profiling::thread_cpu_time()
                .saturating_sub(cpu)
                .as_nanos()
        ));
    }
    workspace.analyzer().record_read(ReadKey::lookup(
        LookupKind::RustDropSubject,
        LookupQuestion::RustDropSubject {
            rel_path: rel_path.into(),
            blob: blob.as_bytes().try_into().expect("fixed-width OID"),
            start_byte,
            end_byte,
        },
        drop_subject_digest(&selection),
    ));
    Ok(selection)
}

fn drop_subject_digest(
    selection: &std::result::Result<
        brokk_bifrost_analysis::analyzer::store::rust_drop_inventory::RustDropInventorySubject,
        brokk_bifrost_analysis::analyzer::store::rust_drop_inventory::RustDropInventoryReason,
    >,
) -> brokk_bifrost_semantic::analyzer::semantic::ids::StableDigest {
    use brokk_bifrost_analysis::analyzer::store::rust_drop_inventory::RustDropInventoryReason;
    let mut hash = brokk_bifrost_core::analyzer::canonical_hash::CanonicalHasher::new(
        b"bifrost:rust-drop-subject:v1",
    );
    match selection {
        Ok(subject) => {
            hash.value(b"selected");
            hash.value(subject.owning_unit.as_bytes());
            hash.value(subject.module_path.as_bytes());
            hash.value(subject.identity_digest.as_bytes());
            hash.value(subject.config_digest.as_bytes());
        }
        Err(RustDropInventoryReason::OwnerMissing) => hash.value(b"missing"),
        Err(RustDropInventoryReason::OwnerAmbiguous) => hash.value(b"ambiguous"),
        Err(reason) => unreachable!("subject selection returned inventory reason {reason:?}"),
    }
    brokk_bifrost_semantic::analyzer::semantic::ids::StableDigest::from_array(hash.finish())
}

/// Read and record one selected nominal declaration's Drop inventory.
/// Content negatives retain their recorded selection; operational stops carry
/// their cause explicitly instead of sharing a missing-answer sentinel.
#[derive(Debug)]
pub enum RustDropInventoryProof {
    Answer(brokk_bifrost_analysis::analyzer::store::rust_drop_inventory::RustDropInventory),
    Stopped(brokk_bifrost_analysis::analyzer::read_ledger::DerivationExecutionCause),
}

// Preserve the typed store error before crossing the semantic provider's
// store-independent error boundary. The proof consumer must not recreate it.
pub(super) fn drop_store_failure(
    analyzer: &dyn brokk_bifrost_analysis::analyzer::IAnalyzer,
    error: brokk_bifrost_analysis::analyzer::store::StoreError,
) -> SemanticProviderError {
    let message = error.to_string();
    analyzer.record_query_failure(error);
    SemanticProviderError::internal(message)
}

/// Read the inventory or a typed stop for this selected declaration.
pub fn rust_drop_inventory_proof(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    declaration: &brokk_bifrost_core::analyzer::model::CodeUnit,
    selected_blob: &git2::Oid,
    declaration_bytes: std::ops::Range<usize>,
    request: &mut SemanticRequest<'_>,
) -> Result<RustDropInventoryProof, SemanticProviderError> {
    use brokk_bifrost_analysis::analyzer::read_ledger::DerivationExecutionCause;
    use brokk_bifrost_analysis::analyzer::read_ledger::{LookupKind, LookupQuestion, ReadKey};
    use brokk_bifrost_analysis::analyzer::store::rust_drop_inventory::RustDropInventory;
    use brokk_bifrost_analysis::analyzer::store::rust_drop_inventory::RustDropInventoryReason;
    let analyzer = workspace.analyzer();
    if request.cancellation.is_cancelled() {
        return Ok(RustDropInventoryProof::Stopped(
            DerivationExecutionCause::Cancelled,
        ));
    }
    let Some(store) = workspace.store() else {
        super::std_types::unavailable_proof_input("drop_inventory_store_unavailable");
        return Ok(RustDropInventoryProof::Stopped(
            DerivationExecutionCause::Provider,
        ));
    };
    let Some(snapshots) = analyzer.selected_workspace_snapshots_for_reads() else {
        super::std_types::unavailable_proof_input("drop_inventory_snapshots_unavailable");
        return Ok(RustDropInventoryProof::Stopped(
            DerivationExecutionCause::Provider,
        ));
    };
    let rel_path = brokk_bifrost_analysis::path_utils::rel_path_string(declaration.source());
    let subject = selected_drop_subject(
        workspace,
        &snapshots,
        &rel_path,
        selected_blob,
        declaration_bytes.start,
        declaration_bytes.end,
    )
    .map_err(|error| drop_store_failure(analyzer, error))?;
    // A clone is an overlay view, not a new canonical unit publication. Read
    // membership even for an empty overlay, so a later edit invalidates reuse.
    let overlays = analyzer.project().overlay_content();
    let selection_digest = drop_subject_digest(&subject);
    let subject = match subject {
        Ok(subject) => subject,
        Err(reason) => {
            return Ok(RustDropInventoryProof::Answer(RustDropInventory::Unknown {
                reason,
                digest: selection_digest,
            }));
        }
    };
    if let Some(overlays) = overlays {
        for (file, _, oid) in overlays.entries_with_blob_ids() {
            request.budget.charge_work(SemanticWork {
                nested_entries: 1,
                ..SemanticWork::default()
            });
            if store
                .rust_drop_inventory_overlay_affects(
                    &snapshots,
                    subject.owning_unit,
                    &brokk_bifrost_analysis::path_utils::rel_path_string(file),
                    &oid,
                )
                .map_err(|error| drop_store_failure(analyzer, error))?
            {
                super::std_types::incomplete_proof("overlay_inventory_unavailable");
                return Ok(RustDropInventoryProof::Answer(RustDropInventory::Unknown {
                    reason: RustDropInventoryReason::ModuleUniverseOpen,
                    digest: selection_digest,
                }));
            }
        }
    }
    let question = LookupQuestion::RustDropInventory {
        rel_path: rel_path.into(),
        blob: selected_blob
            .as_bytes()
            .try_into()
            .expect("fixed-width OID"),
        start_byte: declaration_bytes.start,
        end_byte: declaration_bytes.end,
        owning_unit: subject.owning_unit,
        module_path: subject.module_path.clone(),
        identity_digest: subject.identity_digest,
        config_digest: subject.config_digest,
        proof_version: RUST_DROP_INVENTORY_PROOF_VERSION,
    };
    // Without an active registry (or once it retired) this call keeps nothing.
    let memo = analyzer
        .owned_lookup_memo()
        .and_then(|slots| slots.memo::<drop_inventory::RustDropInventoryMemo>())
        .unwrap_or_else(|| {
            std::sync::Arc::new(
                <drop_inventory::RustDropInventoryMemo as brokk_bifrost_core::domain_memo::DomainMemo>::new(
                    store.retention_budget(),
                ),
            )
        });
    let cpu = crate::profiling::enabled().then(crate::profiling::thread_cpu_time);
    let stdlib_revision = super::candidate_macro_admission::selected_stdlib_revision(analyzer);
    let answer = memo
        .retained_answer(
            store,
            &snapshots,
            &subject,
            stdlib_revision.as_deref(),
            request.cancellation,
            || {
                request.budget.charge_work(SemanticWork {
                    nested_entries: 1,
                    ..SemanticWork::default()
                });
            },
        )
        .map_err(|error| drop_store_failure(analyzer, error))?;
    if let Some(cpu) = cpu {
        crate::profiling::note(format!(
            "inert_drop.inventory_answer calls=1 cpu_ns={}",
            crate::profiling::thread_cpu_time()
                .saturating_sub(cpu)
                .as_nanos()
        ));
    }
    if request.cancellation.is_cancelled() {
        return Ok(RustDropInventoryProof::Stopped(
            DerivationExecutionCause::Cancelled,
        ));
    }
    if analyzer.selected_workspace_snapshots_for_reads().as_deref() != Some(snapshots.as_ref()) {
        super::std_types::unavailable_proof_input("drop_inventory_snapshots_changed");
        return Ok(RustDropInventoryProof::Stopped(
            DerivationExecutionCause::Provider,
        ));
    }
    let answer = match answer {
        Ok(answer) => answer,
        Err(cause) => return Ok(RustDropInventoryProof::Stopped(cause)),
    };
    if answer.admit(request.budget).is_err() {
        return Ok(RustDropInventoryProof::Stopped(
            DerivationExecutionCause::Budget,
        ));
    }
    let answer = answer.value;
    let digest = match &answer {
        RustDropInventory::Present { digest, .. }
        | RustDropInventory::Absent { digest }
        | RustDropInventory::Unknown { digest, .. } => *digest,
    };
    analyzer.record_read(ReadKey::lookup(
        LookupKind::RustDropInventory,
        question,
        digest,
    ));
    Ok(RustDropInventoryProof::Answer(answer))
}

/// Query-only proofs for one procedure, memoized by its gap sweep. Persisted
/// lowering remains dependent on its own file. A scoped_identifier selects the
/// VALUE namespace; constants, tuple constructors and enum variants stay open.
pub(crate) fn selected_unit_struct_value_gaps(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    procedure: &ProcedureHandle,
    file: &brokk_bifrost_core::analyzer::model::ProjectFile,
    source: &std::sync::Arc<str>,
    request: &mut SemanticRequest<'_>,
) -> Result<Vec<SemanticGapId>, SemanticProviderError> {
    let Some(tree) = parse_selected_value_source(source, request)? else {
        return Ok(Vec::new());
    };
    let mut operation = None;
    // Group selected ranges by source, in gap order. Each declaration source
    // is snapshotted and parsed once, and its hold and tree are dropped before
    // the next source: retaining all declarations would multiply request memory.
    let mut source_groups = Vec::new();
    let mut source_indices = HashMap::default();
    for gap in procedure.semantics().gaps() {
        if request.cancellation.is_cancelled() {
            return Ok(Vec::new());
        }
        if gap.capability != SemanticCapability::Values || gap.kind != SemanticGapKind::Unknown {
            continue;
        }
        let SemanticGapSubject::Value(value) = gap.subject else {
            continue;
        };
        let value = procedure
            .semantics()
            .value(value)
            .expect("gap value belongs to procedure");
        let mapping = procedure
            .semantics()
            .source_mapping(value.source)
            .expect("gap value has a source mapping");
        let span = mapping.locator.anchor().span();
        let Some(path) = rust_node_at_range(
            &tree,
            RustSourceRange {
                start: span.start_byte() as usize,
                end: span.end_byte() as usize,
            },
        )
        .filter(|node| node.kind() == "scoped_identifier" && !node.has_error()) else {
            continue;
        };
        if operation.is_none() {
            operation = open_nominal_proof_operation(workspace, request.cancellation);
        }
        let Some(operation) = operation.as_mut() else {
            return Ok(Vec::new());
        };
        let cancellation = request.cancellation;
        let mut charge = |entries| {
            request.budget.charge_work(SemanticWork {
                nested_entries: entries,
                ..SemanticWork::default()
            });
            Ok(())
        };
        let (declaration, range, blob) = match resolve_exact_nominal_site(
            workspace,
            file,
            (source, &tree),
            path,
            cancellation,
            &mut charge,
            operation,
        )? {
            ExactNominalSelection::Found(declaration, range, blob) => (declaration, range, blob),
            ExactNominalSelection::Unknown => continue,
            ExactNominalSelection::Stopped => {
                request
                    .budget
                    .note_external_stop(SemanticBudgetDimension::NestedEntries);
                return Ok(Vec::new());
            }
        };
        let index = *source_indices
            .entry(declaration.source().clone())
            .or_insert_with(|| {
                let index = source_groups.len();
                source_groups.push((declaration.source().clone(), Vec::new()));
                index
            });
        source_groups[index].1.push((gap.id, range, blob));
    }
    let mut proven = Vec::new();
    for (owner, candidates) in source_groups {
        if request.cancellation.is_cancelled() {
            break;
        }
        let selected_blob = candidates[0].2;
        if candidates.iter().any(|(_, _, blob)| *blob != selected_blob) {
            workspace.analyzer().record_query_incomplete(
                brokk_bifrost_analysis::analyzer::QueryReadIncomplete::SemanticEvidenceUnavailable(
                    "selected Rust value declarations read more than one source generation".into(),
                ),
            );
            continue;
        }
        let snapshot;
        let declaration_source = if owner == *file {
            source.as_ref()
        } else {
            let Some(held) = workspace
                .held_program_semantics_artifact_source(&owner, request)?
                .held_or_refused()?
            else {
                break;
            };
            snapshot = held;
            snapshot.source()
        };
        if !selected_nominal_source_matches_range(workspace, declaration_source, selected_blob) {
            continue;
        }
        let declaration_tree;
        let selected_tree = if owner == *file {
            &tree
        } else {
            let Some(parsed) = parse_selected_value_source(declaration_source, request)? else {
                break;
            };
            declaration_tree = parsed;
            &declaration_tree
        };
        for (gap, range, _) in candidates {
            if request.cancellation.is_cancelled() {
                return Ok(proven);
            }
            if rust_node_at_range(
                selected_tree,
                RustSourceRange {
                    start: range.start_byte,
                    end: range.end_byte,
                },
            )
            .is_some_and(|item| {
                item.kind() == "struct_item"
                    && !item.has_error()
                    && item.child_by_field_name("body").is_none()
                    && item.child_by_field_name("type_parameters").is_none()
            }) {
                proven.push(gap);
            }
        }
    }
    Ok(proven)
}

fn parse_selected_value_source(
    source: &str,
    request: &mut SemanticRequest<'_>,
) -> Result<Option<tree_sitter::Tree>, SemanticProviderError> {
    request.budget.charge_work(SemanticWork {
        source_bytes: source.len(),
        ..SemanticWork::default()
    });
    let mut parser = tree_sitter::Parser::new();
    parser
        .set_language(&tree_sitter_rust::LANGUAGE.into())
        .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
    let mut read = |offset: usize, _| &source.as_bytes()[offset..];
    let mut progress = |_: &tree_sitter::ParseState| {
        request.cancellation.is_cancelled() || std::time::Instant::now() >= deadline
    };
    let tree = parser.parse_with_options(
        &mut read,
        None,
        Some(tree_sitter::ParseOptions::new().progress_callback(&mut progress)),
    );
    if tree.is_none() && !request.cancellation.is_cancelled() {
        request
            .budget
            .note_external_stop(SemanticBudgetDimension::NestedEntries);
    }
    Ok(tree)
}

/// Classify a whole bare nominal annotation using its exact selected declaration.
/// A stopped read is recorded on the request before returning Unknown.
fn selected_nominal_annotation_ownership(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    file: &brokk_bifrost_core::analyzer::model::ProjectFile,
    source: &str,
    tree: &tree_sitter::Tree,
    annotation: Node<'_>,
    request: &mut SemanticRequest<'_>,
    operation: &mut brokk_bifrost_analysis::analyzer::store::resolution_operation::SelectedResolutionOperation<'_, '_>,
) -> Result<
    brokk_bifrost_analysis::analyzer::languages::SelectedCallResultOwnership,
    SemanticProviderError,
> {
    use brokk_bifrost_analysis::analyzer::languages::SelectedCallResultOwnership as Ownership;
    if annotation.kind() != "type_identifier" {
        return Ok(Ownership::Unknown);
    }
    let cancellation = request.cancellation;
    let nested_limit = request.budget.limits().nested_entries;
    let mut charge = |entries| {
        if cancellation.is_cancelled() {
            return Err(SemanticProviderError::internal("ownership proof cancelled"));
        }
        request
            .budget
            .check_admission(SemanticWork {
                nested_entries: entries,
                ..SemanticWork::default()
            })
            .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
        request.budget.charge_work(SemanticWork {
            nested_entries: entries,
            ..SemanticWork::default()
        });
        Ok(())
    };
    let (declaration, range, selected_blob) = match resolve_exact_nominal_site(
        workspace,
        file,
        (source, tree),
        annotation,
        cancellation,
        &mut charge,
        operation,
    )? {
        ExactNominalSelection::Found(declaration, range, blob) => (declaration, range, blob),
        ExactNominalSelection::Unknown => return Ok(Ownership::Unknown),
        ExactNominalSelection::Stopped => {
            drop(charge);
            request.budget.note_external_stop(
                brokk_bifrost_semantic::analyzer::semantic::SemanticBudgetDimension::NestedEntries,
            );
            return Ok(Ownership::Unknown);
        }
    };
    drop(charge);
    let Some(decl_snapshot) = workspace
        .held_program_semantics_artifact_source(declaration.source(), request)?
        .held_or_refused()?
    else {
        return Ok(Ownership::Unknown);
    };
    let mut charge = |entries| {
        if cancellation.is_cancelled() {
            return Err(SemanticProviderError::internal("ownership proof cancelled"));
        }
        request
            .budget
            .check_admission(SemanticWork {
                nested_entries: entries,
                ..SemanticWork::default()
            })
            .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
        request.budget.charge_work(SemanticWork {
            nested_entries: entries,
            ..SemanticWork::default()
        });
        Ok(())
    };
    // The generation check hashes every source byte, so the bytes are charged
    // before it and a refused proof still pays for its work.
    charge(decl_snapshot.source().len())?;
    // The declaration range is meaningful only for the blob selected by its
    // range query. A fresh source read may cross a same-length edit; read-set
    // verification is for reuse and cannot certify this fresh proof.
    if !selected_nominal_source_matches_range(workspace, decl_snapshot.source(), selected_blob) {
        return Ok(Ownership::Unknown);
    }
    let mut decl_parser = tree_sitter::Parser::new();
    decl_parser
        .set_language(&tree_sitter_rust::LANGUAGE.into())
        .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
    let decl_deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
    let mut decl_timed_out = false;
    let mut decl_read = |offset: usize, _| &decl_snapshot.source().as_bytes()[offset..];
    let mut decl_progress = |_: &tree_sitter::ParseState| {
        decl_timed_out = std::time::Instant::now() >= decl_deadline;
        decl_timed_out || cancellation.is_cancelled()
    };
    let decl_tree = decl_parser.parse_with_options(
        &mut decl_read,
        None,
        Some(tree_sitter::ParseOptions::new().progress_callback(&mut decl_progress)),
    );
    drop(decl_progress);
    if decl_timed_out || std::time::Instant::now() >= decl_deadline || cancellation.is_cancelled() {
        if decl_timed_out && !cancellation.is_cancelled() {
            drop(charge);
            request.budget.note_external_stop(
                brokk_bifrost_semantic::analyzer::semantic::SemanticBudgetDimension::NestedEntries,
            );
        }
        return Ok(Ownership::Unknown);
    }
    let Some(decl_tree) = decl_tree else {
        return Ok(Ownership::Unknown);
    };
    if decl_tree.root_node().has_error() {
        return Ok(Ownership::Unknown);
    }
    if range.start_byte >= range.end_byte || range.end_byte > decl_snapshot.source().len() {
        return Ok(Ownership::Unknown);
    }
    let mut node = decl_tree.root_node();
    loop {
        charge(1)?;
        if node.start_byte() == range.start_byte && node.end_byte() == range.end_byte {
            break;
        }
        let Some(child) = node.named_children(&mut node.walk()).find(|child| {
            child.start_byte() <= range.start_byte && range.end_byte <= child.end_byte()
        }) else {
            return Ok(Ownership::Unknown);
        };
        node = child;
    }
    if !matches!(node.kind(), "struct_item" | "enum_item") {
        return Ok(Ownership::Unknown);
    }
    let index = RustOwnershipIndex::build(
        decl_tree.root_node(),
        decl_snapshot.source(),
        nested_limit,
        &mut charge,
    )?;
    let classification = index.classify_selected_nominal_declaration(node);
    let local = match classification {
        RustOwnershipClass::Move => Ownership::Move,
        RustOwnershipClass::ScalarCopy | RustOwnershipClass::AggregateCopy => Ownership::Copy,
        _ => Ownership::Unknown,
    };
    if classification != RustOwnershipClass::Incomplete(RustOwnershipIncomplete::UnsupportedType)
        || node.child_by_field_name("type_parameters").is_some()
    {
        return Ok(local);
    }
    // Whether a nongeneric nominal implements Copy is not decided by its
    // fields. The exact selected crate census below proves absence for both
    // payload and fieldless declarations, or keeps the answer unknown.
    charge(1)?;
    let unavailable = |reason: &str| {
        workspace.analyzer().record_query_incomplete(
            brokk_bifrost_analysis::analyzer::QueryReadIncomplete::SemanticEvidenceUnavailable(
                reason.into(),
            ),
        );
    };
    let Some(store) = workspace.store() else {
        unavailable("rust_copy.target_unavailable");
        return Ok(local);
    };
    let Some(snapshots) = workspace
        .analyzer()
        .selected_workspace_snapshots_for_reads()
    else {
        unavailable("rust_copy.target_unavailable");
        return Ok(local);
    };
    let rel_path = brokk_bifrost_analysis::path_utils::rel_path_string(declaration.source());
    let question = store
        .rust_copy_absence_question(
            snapshots.as_ref(),
            &rel_path,
            &selected_blob,
            range.start_byte,
            range.end_byte,
        )
        .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
    let Some(question) = question else {
        unavailable("rust_copy.target_unavailable");
        return Ok(local);
    };
    drop(charge);
    let stdlib_revision =
        super::candidate_macro_admission::selected_stdlib_revision(workspace.analyzer());
    let answer = store
        .rust_copy_absence_answer(
            snapshots.as_ref(),
            &question,
            stdlib_revision.as_deref(),
            cancellation,
            || {
                request.budget.charge_work(SemanticWork {
                    nested_entries: 1,
                    ..SemanticWork::default()
                })
            },
        )
        .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
    match answer {
        Some((
            brokk_bifrost_analysis::analyzer::store::rust_copy_absence::RustCopyAbsence::Absent {
                digest,
            },
            _,
        )) => {
            workspace.analyzer().record_read(
                brokk_bifrost_analysis::analyzer::read_ledger::ReadKey::lookup(
                    brokk_bifrost_analysis::analyzer::read_ledger::LookupKind::RustCopyAbsence,
                    question,
                    digest,
                ),
            );
            Ok(Ownership::Move)
        }
        Some((
            brokk_bifrost_analysis::analyzer::store::rust_copy_absence::RustCopyAbsence::Unknown(
                reason,
            ),
            _,
        )) => {
            unavailable(reason.label());
            Ok(local)
        }
        None => {
            unavailable("rust_copy.target_unavailable");
            Ok(local)
        }
    }
}

pub(crate) fn selected_call_result_ownership(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    callee: &ProcedureHandle,
    request: &mut SemanticRequest<'_>,
) -> Result<
    brokk_bifrost_analysis::analyzer::languages::SelectedCallResultOwnership,
    SemanticProviderError,
> {
    use brokk_bifrost_analysis::analyzer::languages::SelectedCallResultOwnership as Ownership;
    let refusal_before = request.budget.refusal_count();
    let proof = (|| -> Result<Ownership, SemanticProviderError> {
        let key = callee.artifact().key();
        let Some(file) = workspace
            .analyzer()
            .project()
            .file_by_rel_path(std::path::Path::new(key.path().as_str()))
        else {
            return Ok(Ownership::Unknown);
        };
        let Some(snapshot) = workspace
            .held_program_semantics_artifact_source(&file, request)?
            .held_or_refused()?
        else {
            return Ok(Ownership::Unknown);
        };
        if snapshot.key() != key {
            return Ok(Ownership::Unknown);
        }
        let cancellation = request.cancellation;
        let nested_limit = request.budget.limits().nested_entries;
        let mut charge = |entries| {
            if cancellation.is_cancelled() {
                return Err(SemanticProviderError::internal(
                    "ownership proof cancelled or exhausted",
                ));
            }
            request
                .budget
                .check_admission(SemanticWork {
                    nested_entries: entries,
                    ..SemanticWork::default()
                })
                .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
            request.budget.charge_work(SemanticWork {
                nested_entries: entries,
                ..SemanticWork::default()
            });
            Ok(())
        };
        // The source size is bounded by the snapshot reader. Account for parsing
        // that whole source before the index starts its own charged walk.
        charge(snapshot.source().len())?;
        let mut parser = tree_sitter::Parser::new();
        parser
            .set_language(&tree_sitter_rust::LANGUAGE.into())
            .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let mut timed_out = false;
        let mut read = |offset: usize, _| &snapshot.source().as_bytes()[offset..];
        let mut progress = |_: &tree_sitter::ParseState| {
            timed_out = std::time::Instant::now() >= deadline;
            timed_out || cancellation.is_cancelled()
        };
        let tree = parser.parse_with_options(
            &mut read,
            None,
            Some(tree_sitter::ParseOptions::new().progress_callback(&mut progress)),
        );
        drop(progress);
        if timed_out || std::time::Instant::now() >= deadline || cancellation.is_cancelled() {
            if timed_out && !cancellation.is_cancelled() {
                // The parser's time bound is a normal proof budget stop. Record it
                // on the request so no caller can retain this Unknown as content.
                request.budget.note_external_stop(
                brokk_bifrost_semantic::analyzer::semantic::SemanticBudgetDimension::NestedEntries,
            );
            }
            return Ok(Ownership::Unknown);
        }
        let Some(tree) = tree else {
            return Ok(Ownership::Unknown);
        };
        if tree.root_node().has_error() {
            return Ok(Ownership::Unknown);
        }
        let span = callee.semantics().locator().anchor().span();
        let (start, end) = (span.start_byte() as usize, span.end_byte() as usize);
        let mut function = tree.root_node();
        while function.start_byte() != start || function.end_byte() != end {
            charge(1)?;
            let children = function.named_child_count();
            charge(children)?;
            let Some(child) = (0..children)
                .filter_map(|index| function.named_child(index))
                .find(|child| child.start_byte() <= start && end <= child.end_byte())
            else {
                return Ok(Ownership::Unknown);
            };
            function = child;
        }
        charge(1)?;
        // The producer anchors the callable node itself. Never climb from a
        // closure or nested body to an enclosing function's return annotation.
        if !matches!(
            callee.semantics().kind(),
            ProcedureKind::Function | ProcedureKind::Method | ProcedureKind::LocalFunction
        ) || function.kind() != "function_item"
        {
            return Ok(Ownership::Unknown);
        }
        let Some(return_type) = function.child_by_field_name("return_type") else {
            return Ok(Ownership::Unknown);
        };
        // The selected resolver below owns impl-scope Self. A local index
        // refusal must reach that exact-declaration proof rather than bypass it.
        let index = RustOwnershipIndex::build(
            tree.root_node(),
            snapshot.source(),
            nested_limit,
            &mut charge,
        )?;
        let local = match index.classify_type_bounded(return_type, &mut charge)? {
            RustOwnershipClass::Move => Ownership::Move,
            RustOwnershipClass::ScalarCopy | RustOwnershipClass::AggregateCopy => Ownership::Copy,
            _ => Ownership::Unknown,
        };
        if local != Ownership::Unknown {
            return Ok(local);
        }
        drop(charge);
        let Some(mut operation) = open_nominal_proof_operation(workspace, request.cancellation)
        else {
            return Ok(Ownership::Unknown);
        };
        selected_nominal_annotation_ownership(
            workspace,
            &file,
            snapshot.source(),
            &tree,
            return_type,
            request,
            &mut operation,
        )
    })();
    if request.cancellation.is_cancelled() || request.budget.refusal_count() > refusal_before {
        Ok(Ownership::Unknown)
    } else {
        proof
    }
}

/// A formal summary uses only its own selected declaration and type. It must
/// not inherit a caller's substitution or a same-spelled type in another file.
pub(crate) fn selected_formal_ownership(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    callee: &ProcedureHandle,
    formal_query: ProcedurePortKind,
    request: &mut SemanticRequest<'_>,
) -> Result<
    brokk_bifrost_analysis::analyzer::languages::SelectedCallResultOwnership,
    SemanticProviderError,
> {
    use brokk_bifrost_analysis::analyzer::languages::SelectedCallResultOwnership as Ownership;
    let refusal_before = request.budget.refusal_count();
    let proof = (|| -> Result<Ownership, SemanticProviderError> {
        if formal_query == ProcedurePortKind::Receiver {
            return selected_receiver_formal_ownership(workspace, callee, request);
        }
        let ProcedurePortKind::Parameter { ordinal } = formal_query else {
            return Ok(Ownership::Unknown);
        };
        let key = callee.artifact().key();
        let Some(file) = workspace
            .analyzer()
            .project()
            .file_by_rel_path(std::path::Path::new(key.path().as_str()))
        else {
            return Ok(Ownership::Unknown);
        };
        let Some(snapshot) = workspace
            .held_program_semantics_artifact_source(&file, request)?
            .held_or_refused()?
        else {
            return Ok(Ownership::Unknown);
        };
        if snapshot.key() != key {
            return Ok(Ownership::Unknown);
        }
        let cancellation = request.cancellation;
        let mut charge = |entries| {
            if cancellation.is_cancelled() {
                return Err(SemanticProviderError::internal(
                    "formal ownership proof cancelled",
                ));
            }
            request
                .budget
                .check_admission(SemanticWork {
                    nested_entries: entries,
                    ..SemanticWork::default()
                })
                .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
            request.budget.charge_work(SemanticWork {
                nested_entries: entries,
                ..SemanticWork::default()
            });
            Ok(())
        };
        charge(snapshot.source().len())?;
        let mut parser = tree_sitter::Parser::new();
        parser
            .set_language(&tree_sitter_rust::LANGUAGE.into())
            .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let mut timed_out = false;
        let mut read = |offset: usize, _| &snapshot.source().as_bytes()[offset..];
        let mut progress = |_: &tree_sitter::ParseState| {
            timed_out = std::time::Instant::now() >= deadline;
            timed_out || cancellation.is_cancelled()
        };
        let tree = parser.parse_with_options(
            &mut read,
            None,
            Some(tree_sitter::ParseOptions::new().progress_callback(&mut progress)),
        );
        drop(progress);
        if timed_out || std::time::Instant::now() >= deadline || cancellation.is_cancelled() {
            if timed_out && !cancellation.is_cancelled() {
                drop(charge);
                request.budget.note_external_stop(
                    brokk_bifrost_semantic::analyzer::semantic::SemanticBudgetDimension::NestedEntries,
                );
            }
            return Ok(Ownership::Unknown);
        }
        let Some(tree) = tree else {
            return Ok(Ownership::Unknown);
        };
        if tree.root_node().has_error() {
            return Ok(Ownership::Unknown);
        }
        let span = callee.semantics().locator().anchor().span();
        let (start, end) = (span.start_byte() as usize, span.end_byte() as usize);
        let mut function = tree.root_node();
        while function.start_byte() != start || function.end_byte() != end {
            charge(1)?;
            let children = function.named_child_count();
            charge(children)?;
            let Some(child) = (0..children)
                .filter_map(|index| function.named_child(index))
                .find(|child| child.start_byte() <= start && end <= child.end_byte())
            else {
                return Ok(Ownership::Unknown);
            };
            function = child;
        }
        charge(1)?;
        if !matches!(
            callee.semantics().kind(),
            ProcedureKind::Function | ProcedureKind::Method | ProcedureKind::LocalFunction
        ) || function.kind() != "function_item"
        {
            return Ok(Ownership::Unknown);
        }
        let Some(parameters) = function.child_by_field_name("parameters") else {
            return Ok(Ownership::Unknown);
        };
        let mut cursor = parameters.walk();
        let parameter = parameters
            .named_children(&mut cursor)
            .filter(|node| node.kind() == "parameter")
            .nth(ordinal as usize);
        let Some(parameter) = parameter else {
            return Ok(Ownership::Unknown);
        };
        charge(parameters.named_child_count())?;
        let Some(formal) = callee.semantics().values().iter().find(|value| {
            matches!(value.kind, SemanticValueKind::Parameter {
                ordinal: actual,
                multiplicity: FormalMultiplicity::One,
                ..
            } if actual == ordinal)
        }) else {
            return Ok(Ownership::Unknown);
        };
        let Some(mapping) = callee.semantics().source_mapping(formal.source) else {
            return Ok(Ownership::Unknown);
        };
        let formal_span = mapping.locator.anchor().span();
        if formal_span.start_byte() as usize != parameter.start_byte()
            || formal_span.end_byte() as usize != parameter.end_byte()
            || parameter
                .child_by_field_name("pattern")
                .is_none_or(|pattern| pattern.kind() != "identifier")
        {
            return Ok(Ownership::Unknown);
        }
        let Some(annotation) = parameter.child_by_field_name("type") else {
            return Ok(Ownership::Unknown);
        };
        // Preserve the full annotation. A reference, pointer, generic,
        // projection, Self, or unsupported alias has no bare nominal proof.
        if annotation.kind() != "type_identifier"
            || &snapshot.source()[annotation.byte_range()] == "Self"
        {
            return Ok(Ownership::Unknown);
        }
        drop(charge);
        let Some(mut operation) = open_nominal_proof_operation(workspace, request.cancellation)
        else {
            return Ok(Ownership::Unknown);
        };
        selected_nominal_annotation_ownership(
            workspace,
            &file,
            snapshot.source(),
            &tree,
            annotation,
            request,
            &mut operation,
        )
    })();
    if request.cancellation.is_cancelled() || request.budget.refusal_count() > refusal_before {
        Ok(Ownership::Unknown)
    } else {
        proof
    }
}

// The receiver's type comes from this exact grammar owner, never from a
// nearest-impl search or the method's return annotation.
fn selected_receiver_declared_type(parameter: Node<'_>) -> Option<Node<'_>> {
    if parameter.kind() != "self_parameter"
        || rust_self_parameter_is_borrowed(parameter)
        || parameter.child_by_field_name("type").is_some()
    {
        return None;
    }
    let parameters = parameter.parent()?;
    let function = parameters.parent()?;
    let declarations = function.parent()?;
    let implementation = declarations.parent()?;
    if parameters.kind() != "parameters"
        || function.kind() != "function_item"
        || function.child_by_field_name("parameters") != Some(parameters)
        || declarations.kind() != "declaration_list"
        || implementation.kind() != "impl_item"
        || implementation.child_by_field_name("body") != Some(declarations)
        || implementation
            .child_by_field_name("type_parameters")
            .is_some()
    {
        return None;
    }
    let ty = implementation.child_by_field_name("type")?;
    (ty.kind() == "type_identifier").then_some(ty)
}

fn selected_receiver_formal_ownership(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    callee: &ProcedureHandle,
    request: &mut SemanticRequest<'_>,
) -> Result<
    brokk_bifrost_analysis::analyzer::languages::SelectedCallResultOwnership,
    SemanticProviderError,
> {
    use brokk_bifrost_analysis::analyzer::languages::SelectedCallResultOwnership as Ownership;
    if request.stop_observed() {
        return Ok(Ownership::Unknown);
    }
    let Some(file) = workspace
        .analyzer()
        .project()
        .file_by_rel_path(std::path::Path::new(
            callee.artifact().key().path().as_str(),
        ))
    else {
        return Ok(Ownership::Unknown);
    };
    let Some(snapshot) = workspace
        .held_program_semantics_artifact_source(&file, request)?
        .held_or_refused()?
    else {
        return Ok(Ownership::Unknown);
    };
    if snapshot.key() != callee.artifact().key() {
        return Ok(Ownership::Unknown);
    }
    let Some(tree) = parse_selected_value_source(snapshot.source(), request)? else {
        return Ok(Ownership::Unknown);
    };
    if tree.root_node().has_error() {
        return Ok(Ownership::Unknown);
    }
    let mut receivers = callee.semantics().values().iter().filter(|v| {
        matches!(
            v.kind,
            SemanticValueKind::Receiver {
                mode: ReceiverMode::Owned,
                ..
            }
        )
    });
    let Some(formal) = receivers.next() else {
        return Ok(Ownership::Unknown);
    };
    if receivers.next().is_some() {
        return Ok(Ownership::Unknown);
    }
    let Some(mapping) = callee.semantics().source_mapping(formal.source) else {
        return Ok(Ownership::Unknown);
    };
    if mapping.kind != SourceMappingKind::Exact {
        return Ok(Ownership::Unknown);
    }
    let span = mapping.locator.anchor().span();
    let Some(parameter) = rust_node_at_range(
        &tree,
        RustSourceRange {
            start: span.start_byte() as usize,
            end: span.end_byte() as usize,
        },
    ) else {
        return Ok(Ownership::Unknown);
    };
    // A bare self token and its self_parameter have the same exact span.
    // Select that one verified grammar parent, rather than treating the leaf
    // returned by named_descendant_for_byte_range as the formal declaration.
    let parameter = if parameter.kind() == "self" {
        parameter
            .parent()
            .filter(|parent| {
                parent.kind() == "self_parameter" && parent.byte_range() == parameter.byte_range()
            })
            .unwrap_or(parameter)
    } else {
        parameter
    };
    let Some(annotation) = selected_receiver_declared_type(parameter) else {
        return Ok(Ownership::Unknown);
    };
    let function = parameter
        .parent()
        .and_then(|p| p.parent())
        .expect("verified grammar parents");
    let span = callee.semantics().locator().anchor().span();
    if function.start_byte() != span.start_byte() as usize
        || function.end_byte() != span.end_byte() as usize
    {
        return Ok(Ownership::Unknown);
    }
    let Some(mut operation) = open_nominal_proof_operation(workspace, request.cancellation) else {
        return Ok(Ownership::Unknown);
    };
    let answer = selected_nominal_annotation_ownership(
        workspace,
        &file,
        snapshot.source(),
        &tree,
        annotation,
        request,
        &mut operation,
    )?;
    Ok(if request.stop_observed() {
        Ownership::Unknown
    } else {
        answer
    })
}

/// The Rust-only positive proof for an evaluated whole argument that is an
/// immutable shared-reference formal. The call row supplies the exact actual;
/// syntax and the two events at that actual's evaluation point certify its
/// entry referent. Address values alone carry no such meaning.
pub(crate) fn direct_formal_referent_at_call(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    caller: &ProcedureHandle,
    call: &SemanticCallSite,
    argument_ordinal: u32,
    request: &mut SemanticRequest<'_>,
) -> Result<Option<u32>, SemanticProviderError> {
    use brokk_bifrost_analysis::analyzer::lexical_definitions::{
        LexicalBindingResolution, resolve_lexical_binding_from_focus_with_visibility,
    };
    let refusal_before = request.budget.refusal_count();
    let proof = (|| -> Result<Option<u32>, SemanticProviderError> {
        let semantics = caller.semantics();
        if semantics.call_site(call.id) != Some(call)
            || call.receiver.is_some_and(|receiver| {
                call.arguments
                    .get(argument_ordinal as usize)
                    .is_some_and(|argument| argument.value == receiver)
            })
        {
            return Ok(None);
        }
        let Some(argument) = call.arguments.get(argument_ordinal as usize) else {
            return Ok(None);
        };
        let actual = argument.value;
        if call
            .arguments
            .iter()
            .filter(|row| row.value == actual)
            .count()
            != 1
        {
            return Ok(None);
        }
        let Some(value) = semantics.value(actual) else {
            return Ok(None);
        };
        if value.kind != SemanticValueKind::Address {
            return Ok(None);
        }
        let Some(mapping) = semantics.source_mapping(value.source) else {
            return Ok(None);
        };
        if mapping.kind != SourceMappingKind::Exact {
            return Ok(None);
        }
        let key = caller.artifact().key();
        let Some(file) = workspace
            .analyzer()
            .project()
            .file_by_rel_path(std::path::Path::new(key.path().as_str()))
        else {
            return Ok(None);
        };
        let Some(snapshot) = workspace
            .held_program_semantics_artifact_source(&file, request)?
            .held_or_refused()?
        else {
            return Ok(None);
        };
        if snapshot.key() != key {
            return Ok(None);
        }
        let cancellation = request.cancellation;
        let mut charge = |entries| {
            if cancellation.is_cancelled() {
                return Err(SemanticProviderError::internal(
                    "formal origin proof cancelled",
                ));
            }
            request
                .budget
                .check_admission(SemanticWork {
                    nested_entries: entries,
                    ..SemanticWork::default()
                })
                .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
            request.budget.charge_work(SemanticWork {
                nested_entries: entries,
                ..SemanticWork::default()
            });
            Ok(())
        };
        charge(snapshot.source().len())?;
        let mut parser = tree_sitter::Parser::new();
        parser
            .set_language(&tree_sitter_rust::LANGUAGE.into())
            .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let mut timed_out = false;
        let mut read = |offset: usize, _| &snapshot.source().as_bytes()[offset..];
        let mut progress = |_: &tree_sitter::ParseState| {
            timed_out = std::time::Instant::now() >= deadline;
            timed_out || cancellation.is_cancelled()
        };
        let tree = parser.parse_with_options(
            &mut read,
            None,
            Some(tree_sitter::ParseOptions::new().progress_callback(&mut progress)),
        );
        drop(progress);
        if timed_out || std::time::Instant::now() >= deadline || cancellation.is_cancelled() {
            if timed_out && !cancellation.is_cancelled() {
                drop(charge);
                request.budget.note_external_stop(
                    brokk_bifrost_semantic::analyzer::semantic::SemanticBudgetDimension::NestedEntries,
                );
            }
            return Ok(None);
        }
        let Some(tree) = tree else { return Ok(None) };
        if tree.root_node().has_error() {
            return Ok(None);
        }
        let actual_span = mapping.locator.anchor().span();
        let Some(node) = tree.root_node().descendant_for_byte_range(
            actual_span.start_byte() as usize,
            actual_span.end_byte() as usize,
        ) else {
            return Ok(None);
        };
        charge(1)?;
        if node.kind() != "identifier"
            || node.start_byte() != actual_span.start_byte() as usize
            || node.end_byte() != actual_span.end_byte() as usize
        {
            return Ok(None);
        }
        let Some(arguments) = node.parent() else {
            return Ok(None);
        };
        let Some(call_node) = arguments.parent() else {
            return Ok(None);
        };
        let Some(call_mapping) = semantics.source_mapping(call.source) else {
            return Ok(None);
        };
        let call_span = call_mapping.locator.anchor().span();
        if arguments.kind() != "arguments"
            || call_node.kind() != "call_expression"
            || call_node.start_byte() != call_span.start_byte() as usize
            || call_node.end_byte() != call_span.end_byte() as usize
            || call_arguments(call_node)
                .get(argument_ordinal as usize)
                .is_none_or(|selected| selected.id() != node.id())
        {
            return Ok(None);
        }
        let Some(binding) = resolve_lexical_binding_from_focus_with_visibility(
            brokk_bifrost_analysis::analyzer::Language::Rust,
            node,
            snapshot.source(),
            node.start_byte(),
            node_text(snapshot.source(), node).unwrap_or_default(),
        )
        .ok()
        .flatten() else {
            return Ok(None);
        };
        let LexicalBindingResolution::Parameter(definition) = binding else {
            return Ok(None);
        };
        let span = semantics.locator().anchor().span();
        let mut function = tree.root_node();
        while function.start_byte() != span.start_byte() as usize
            || function.end_byte() != span.end_byte() as usize
        {
            charge(1 + function.named_child_count())?;
            let Some(child) = (0..function.named_child_count())
                .filter_map(|index| function.named_child(index))
                .find(|child| {
                    child.start_byte() <= span.start_byte() as usize
                        && span.end_byte() as usize <= child.end_byte()
                })
            else {
                return Ok(None);
            };
            function = child;
        }
        if function.kind() != "function_item"
            || !matches!(
                semantics.kind(),
                ProcedureKind::Function | ProcedureKind::Method | ProcedureKind::LocalFunction
            )
        {
            return Ok(None);
        }
        let Some(slots) = brokk_bifrost_analysis::analyzer::lexical_definitions::formal_parameter_slots_for_owner_with_nodes(
            brokk_bifrost_analysis::analyzer::Language::Rust,
            function,
            snapshot.source(),
        ) else { return Ok(None) };
        charge(slots.len())?;
        let mut selected = slots.into_iter().enumerate().filter(|(_, (_, parameter))| {
            definition.declaration_range.start_byte == parameter.start_byte()
                && definition.declaration_range.end_byte == parameter.end_byte()
        });
        let Some((ordinal, (_, parameter))) = selected.next() else {
            return Ok(None);
        };
        if selected.next().is_some()
            || parameter.kind() != "parameter"
            || parameter
                .child_by_field_name("pattern")
                .is_none_or(|pattern| pattern.kind() != "identifier")
        {
            return Ok(None);
        }
        let Some(annotation) = parameter.child_by_field_name("type") else {
            return Ok(None);
        };
        if annotation.kind() != "reference_type"
            || (0..annotation.named_child_count())
                .filter_map(|index| annotation.named_child(index))
                .any(|child| child.kind() == "mutable_specifier")
            || annotation
                .child_by_field_name("type")
                .is_none_or(|inner| inner.kind() != "type_identifier")
        {
            return Ok(None);
        }
        let Some(formal) = semantics.values().iter().find(|row| {
            matches!(row.kind, SemanticValueKind::Parameter {
                ordinal: index,
                multiplicity: FormalMultiplicity::One,
                ..
            } if index == ordinal as u32)
        }) else {
            return Ok(None);
        };
        let Some(formal_mapping) = semantics.source_mapping(formal.source) else {
            return Ok(None);
        };
        let formal_span = formal_mapping.locator.anchor().span();
        if formal_span.start_byte() as usize != parameter.start_byte()
            || formal_span.end_byte() as usize != parameter.end_byte()
        {
            return Ok(None);
        }
        let mut definitions = semantics.points().iter().filter(|point| {
            point.events.iter().any(|event| {
                matches!(event.effect,
                SemanticEffect::ValueFlow { target, .. } | SemanticEffect::Assignment { target, .. }
                    if target == actual)
            })
        });
        let Some(point) = definitions.next() else {
            return Ok(None);
        };
        if definitions.next().is_some() || point.id == call.point {
            return Ok(None);
        }
        let expected = [
            SemanticEffect::ValueFlow {
                kind: ValueFlowKind::Parameter,
                source: formal.id,
                target: actual,
            },
            SemanticEffect::Assignment {
                target: actual,
                value: formal.id,
            },
        ];
        let mut relevant = point.events.iter().filter(|event| {
            matches!(event.effect,
            SemanticEffect::ValueFlow { target, .. } | SemanticEffect::Assignment { target, .. }
                if target == actual)
        });
        for wanted in expected {
            let Some(event) = relevant.next() else {
                return Ok(None);
            };
            let Some(evidence) = semantics.evidence_row(event.evidence) else {
                return Ok(None);
            };
            if event.effect != wanted
                || !matches!(evidence.proof, ProofStatus::Proven)
                || !matches!(evidence.completeness, EvidenceCompleteness::Complete)
            {
                return Ok(None);
            }
        }
        if relevant.next().is_some()
            || semantics.gaps().iter().any(|gap| {
                gap.capability == SemanticCapability::Values
                    && (matches!(gap.subject, SemanticGapSubject::Procedure)
                        || matches!(gap.subject, SemanticGapSubject::Point if gap.point == point.id || gap.point == call.point)
                        || matches!(gap.subject, SemanticGapSubject::Value(value) if value == actual || value == formal.id))
            })
        {
            return Ok(None);
        }
        Ok(Some(ordinal as u32))
    })();
    if request.cancellation.is_cancelled() || request.budget.refusal_count() > refusal_before {
        Ok(None)
    } else {
        proof
    }
}

/// Resolve one selected ordinary formal independently of the call actual.
/// The caller's ValueId is never interpreted in this procedure's value table.
fn selected_formal_nominal_identity(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    procedure: &ProcedureHandle,
    ordinal: u32,
    request: &mut SemanticRequest<'_>,
    operation: &mut brokk_bifrost_analysis::analyzer::store::resolution_operation::SelectedResolutionOperation<'_, '_>,
) -> Result<
    Option<(
        brokk_bifrost_core::analyzer::model::CodeUnit,
        brokk_bifrost_core::analyzer::model::Range,
        brokk_bifrost_semantic::analyzer::semantic::SemanticArtifactKey,
    )>,
    SemanticProviderError,
> {
    if request.stop_observed()
        || procedure.artifact().key().language()
            != brokk_bifrost_core::analyzer::model::LanguageDialect::Standard(
                brokk_bifrost_core::analyzer::model::Language::Rust,
            )
    {
        return Ok(None);
    }
    let refusal_before = request.budget.refusal_count();
    let proof = (|| {
        let key = procedure.artifact().key();
        let Some(file) = workspace
            .analyzer()
            .project()
            .file_by_rel_path(std::path::Path::new(key.path().as_str()))
        else {
            return Ok(None);
        };
        let Some(snapshot) = workspace
            .held_program_semantics_artifact_source(&file, request)?
            .held_or_refused()?
        else {
            return Ok(None);
        };
        if snapshot.key() != key {
            return Ok(None);
        }
        let cancellation = request.cancellation;
        let mut charge = |entries| {
            if cancellation.is_cancelled() {
                return Err(SemanticProviderError::internal(
                    "formal identity proof cancelled",
                ));
            }
            let work = SemanticWork {
                nested_entries: entries,
                ..SemanticWork::default()
            };
            request
                .budget
                .check_admission(work)
                .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
            request.budget.charge_work(work);
            Ok(())
        };
        charge(snapshot.source().len())?;
        let mut parser = tree_sitter::Parser::new();
        parser
            .set_language(&tree_sitter_rust::LANGUAGE.into())
            .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let mut timed_out = false;
        let mut read = |offset: usize, _| &snapshot.source().as_bytes()[offset..];
        let mut progress = |_: &tree_sitter::ParseState| {
            timed_out = std::time::Instant::now() >= deadline;
            timed_out || cancellation.is_cancelled()
        };
        let tree = parser.parse_with_options(
            &mut read,
            None,
            Some(tree_sitter::ParseOptions::new().progress_callback(&mut progress)),
        );
        drop(progress);
        if timed_out || std::time::Instant::now() >= deadline || cancellation.is_cancelled() {
            if timed_out && !cancellation.is_cancelled() {
                drop(charge);
                request.budget.note_external_stop(
                    brokk_bifrost_semantic::analyzer::semantic::SemanticBudgetDimension::NestedEntries,
                );
            }
            return Ok(None);
        }
        let Some(tree) = tree else { return Ok(None) };
        if tree.root_node().has_error() {
            return Ok(None);
        }
        let span = procedure.semantics().locator().anchor().span();
        let (start, end) = (span.start_byte() as usize, span.end_byte() as usize);
        let mut function = tree.root_node();
        while function.start_byte() != start || function.end_byte() != end {
            charge(1)?;
            let children = function.named_child_count();
            charge(children)?;
            let Some(child) = (0..children)
                .filter_map(|i| function.named_child(i))
                .find(|child| child.start_byte() <= start && end <= child.end_byte())
            else {
                return Ok(None);
            };
            function = child;
        }
        charge(1)?;
        if !matches!(
            procedure.semantics().kind(),
            ProcedureKind::Function | ProcedureKind::Method | ProcedureKind::LocalFunction
        ) || function.kind() != "function_item"
        {
            return Ok(None);
        }
        let Some(parameters) = function.child_by_field_name("parameters") else {
            return Ok(None);
        };
        charge(parameters.named_child_count())?;
        let mut cursor = parameters.walk();
        let Some(parameter) = parameters
            .named_children(&mut cursor)
            .filter(|node| node.kind() == "parameter")
            .nth(ordinal as usize)
        else {
            return Ok(None);
        };
        let Some(formal) = procedure.semantics().values().iter().find(|value| {
            matches!(
                value.kind, SemanticValueKind::Parameter {
                    ordinal: found, multiplicity: FormalMultiplicity::One, ..
                } if found == ordinal
            )
        }) else {
            return Ok(None);
        };
        let Some(mapping) = procedure.semantics().source_mapping(formal.source) else {
            return Ok(None);
        };
        let formal_span = mapping.locator.anchor().span();
        if formal_span.start_byte() as usize != parameter.start_byte()
            || formal_span.end_byte() as usize != parameter.end_byte()
            || parameter
                .child_by_field_name("pattern")
                .is_none_or(|pattern| pattern.kind() != "identifier")
        {
            return Ok(None);
        }
        // Reject generic declarations and any enclosing generic context,
        // including lifetime, const, defaulted and where-bound parameters.
        let mut ancestor = Some(function);
        while let Some(node) = ancestor {
            charge(1 + node.named_child_count())?;
            if node.child_by_field_name("type_parameters").is_some()
                || direct_named_child_kind(node, "where_clause").is_some()
            {
                return Ok(None);
            }
            ancestor = node.parent();
        }
        let Some(annotation) = parameter.child_by_field_name("type") else {
            return Ok(None);
        };
        let (declaration, range, selected_blob) = match resolve_exact_nominal_site(
            workspace,
            &file,
            (snapshot.source(), &tree),
            annotation,
            cancellation,
            &mut charge,
            operation,
        )? {
            ExactNominalSelection::Found(unit, range, blob) => (unit, range, blob),
            ExactNominalSelection::Unknown => return Ok(None),
            ExactNominalSelection::Stopped => {
                drop(charge);
                request.budget.note_external_stop(
                    brokk_bifrost_semantic::analyzer::semantic::SemanticBudgetDimension::NestedEntries,
                );
                return Ok(None);
            }
        };
        // The selected declaration's own source, range and node kind are
        // independent of the spelling in either formal annotation.
        drop(charge);
        let Some(decl_snapshot) = workspace
            .held_program_semantics_artifact_source(declaration.source(), request)?
            .held_or_refused()?
        else {
            return Ok(None);
        };
        let mut charge = |entries| {
            if cancellation.is_cancelled() {
                return Err(SemanticProviderError::internal(
                    "formal identity proof cancelled",
                ));
            }
            let work = SemanticWork {
                nested_entries: entries,
                ..SemanticWork::default()
            };
            request
                .budget
                .check_admission(work)
                .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
            request.budget.charge_work(work);
            Ok(())
        };
        charge(decl_snapshot.source().len())?;
        if !selected_nominal_source_matches_range(workspace, decl_snapshot.source(), selected_blob)
        {
            return Ok(None);
        }
        let mut decl_parser = tree_sitter::Parser::new();
        decl_parser
            .set_language(&tree_sitter_rust::LANGUAGE.into())
            .map_err(|error| SemanticProviderError::internal(error.to_string()))?;
        let mut decl_timed_out = false;
        let mut decl_read = |offset: usize, _| &decl_snapshot.source().as_bytes()[offset..];
        let mut decl_progress = |_: &tree_sitter::ParseState| {
            decl_timed_out = std::time::Instant::now() >= deadline;
            decl_timed_out || cancellation.is_cancelled()
        };
        let decl_tree = decl_parser.parse_with_options(
            &mut decl_read,
            None,
            Some(tree_sitter::ParseOptions::new().progress_callback(&mut decl_progress)),
        );
        drop(decl_progress);
        if decl_timed_out || std::time::Instant::now() >= deadline || cancellation.is_cancelled() {
            if decl_timed_out && !cancellation.is_cancelled() {
                drop(charge);
                request.budget.note_external_stop(
                    brokk_bifrost_semantic::analyzer::semantic::SemanticBudgetDimension::NestedEntries,
                );
            }
            return Ok(None);
        }
        let Some(decl_tree) = decl_tree else {
            return Ok(None);
        };
        if decl_tree.root_node().has_error()
            || range.start_byte >= range.end_byte
            || range.end_byte > decl_snapshot.source().len()
        {
            return Ok(None);
        }
        let mut node = decl_tree.root_node();
        loop {
            charge(1)?;
            if node.start_byte() == range.start_byte && node.end_byte() == range.end_byte {
                break;
            }
            let children = node.named_child_count();
            charge(children)?;
            let Some(child) = (0..children)
                .filter_map(|i| node.named_child(i))
                .find(|child| {
                    child.start_byte() <= range.start_byte && range.end_byte <= child.end_byte()
                })
            else {
                return Ok(None);
            };
            node = child;
        }
        if !matches!(node.kind(), "struct_item" | "enum_item") {
            return Ok(None);
        }
        let mut ancestor = Some(node);
        while let Some(candidate) = ancestor {
            charge(1 + candidate.named_child_count())?;
            if candidate.child_by_field_name("type_parameters").is_some()
                || direct_named_child_kind(candidate, "where_clause").is_some()
            {
                return Ok(None);
            }
            ancestor = candidate.parent();
        }
        Ok(Some((declaration, range, decl_snapshot.key().clone())))
    })();
    if request.cancellation.is_cancelled() || request.budget.refusal_count() > refusal_before {
        Ok(None)
    } else {
        proof
    }
}

/// Rust cannot implicitly convert one bare nongeneric nominal value to
/// another in a Value-mode ordinary formal binding.
pub(crate) fn selected_formal_identity_conversion(
    workspace: &brokk_bifrost_analysis::analyzer::workspace::WorkspaceAnalyzer,
    source: &ProcedureHandle,
    source_ordinal: u32,
    target: &ProcedureHandle,
    target_ordinal: u32,
    request: &mut SemanticRequest<'_>,
) -> Result<
    brokk_bifrost_analysis::analyzer::languages::SelectedIdentityConversion,
    SemanticProviderError,
> {
    use brokk_bifrost_analysis::analyzer::languages::SelectedIdentityConversion as Conversion;
    let Some(mut operation) = open_nominal_proof_operation(workspace, request.cancellation) else {
        return Ok(Conversion::Unknown);
    };
    let Some(source_type) = selected_formal_nominal_identity(
        workspace,
        source,
        source_ordinal,
        request,
        &mut operation,
    )?
    else {
        return Ok(Conversion::Unknown);
    };
    if request.cancellation.is_cancelled() || request.budget.refusal_count() > 0 {
        return Ok(Conversion::Unknown);
    }
    let Some(target_type) = selected_formal_nominal_identity(
        workspace,
        target,
        target_ordinal,
        request,
        &mut operation,
    )?
    else {
        return Ok(Conversion::Unknown);
    };
    Ok(
        if source_type == target_type
            && !request.cancellation.is_cancelled()
            && request.budget.refusal_count() == 0
        {
            Conversion::Identity
        } else {
            Conversion::Unknown
        },
    )
}

#[cfg(test)]
mod selected_call_result_ownership_tests {
    use super::*;

    #[test]
    #[brokk_bifrost_test_macros::hardwon(
        "#8386: a field lookup missed Rust where clauses published as named children"
    )]
    fn rust_where_clause_is_a_named_child_not_a_field() {
        let mut parser = tree_sitter::Parser::new();
        parser
            .set_language(&tree_sitter_rust::LANGUAGE.into())
            .unwrap();
        let tree = parser
            .parse("fn f<T>(_: T) where T: Clone {}", None)
            .unwrap();
        let function = tree.root_node().named_child(0).unwrap();
        assert_eq!(function.kind(), "function_item");
        assert!(function.child_by_field_name("where_clause").is_none());
        assert!(direct_named_child_kind(function, "where_clause").is_some());
    }

    #[test]
    #[brokk_bifrost_test_macros::hardwon(
        "#8386: a nested closure inherited its enclosing function's return ownership class"
    )]
    fn closure_does_not_inherit_enclosing_function_return_class() {
        use brokk_bifrost_analysis::analyzer::languages::SelectedCallResultOwnership;
        use brokk_bifrost_analysis::analyzer::semantic::{CancellationToken, SemanticBudget};
        use brokk_bifrost_core::analyzer::config::AnalyzerConfig;
        use brokk_bifrost_core::analyzer::model::Language;

        let project = crate::inline_project::InlineTestProject::with_language(Language::Rust)
            .file("Cargo.toml", "[package]\nname = \"closure_return\"\nversion = \"0.1.0\"\nedition = \"2024\"\n")
            .file("src/lib.rs", "struct Resource { payload: &'static mut u8 } fn outer() -> Resource { let make = || panic!(); make() }")
            .build();
        let workspace = project.workspace_analyzer(AnalyzerConfig::default());
        let cancellation = CancellationToken::default();
        let mut budget = SemanticBudget::default();
        let artifact = workspace
            .materialize_program_semantics(
                &project.file("src/lib.rs"),
                &mut SemanticRequest::new(&mut budget, &cancellation),
            )
            .unwrap()
            .available_value()
            .cloned()
            .unwrap();
        let closure = artifact
            .procedures()
            .iter()
            .find(|procedure| procedure.kind() == ProcedureKind::Closure)
            .unwrap();
        let closure = artifact.procedure_handle(closure.id()).unwrap();
        let mut budget = SemanticBudget::default();
        assert_eq!(
            selected_call_result_ownership(
                &workspace,
                &closure,
                &mut SemanticRequest::new(&mut budget, &cancellation),
            )
            .unwrap(),
            SelectedCallResultOwnership::Unknown,
        );
        let outer = artifact
            .procedures()
            .iter()
            .find(|procedure| procedure.kind() == ProcedureKind::Function)
            .unwrap();
        let outer = artifact.procedure_handle(outer.id()).unwrap();
        let mut limits = SemanticBudget::default().limits();
        limits.nested_entries = 1;
        let mut tiny = SemanticBudget::new(limits).unwrap();
        assert_eq!(
            selected_call_result_ownership(
                &workspace,
                &outer,
                &mut SemanticRequest::new(&mut tiny, &cancellation),
            )
            .unwrap(),
            SelectedCallResultOwnership::Unknown,
        );
        assert!(tiny.refusal_count() > 0);
        // A fresh query must recompute the class; a stopped Unknown is not a
        // stable statement about the selected procedure's content.
        let mut fresh = SemanticBudget::default();
        assert_eq!(
            selected_call_result_ownership(
                &workspace,
                &outer,
                &mut SemanticRequest::new(&mut fresh, &cancellation),
            )
            .unwrap(),
            SelectedCallResultOwnership::Move,
        );
    }

    #[test]
    fn nominal_payload_ownership_keeps_copy_inventory_boundaries() {
        use brokk_bifrost_analysis::analyzer::languages::SelectedCallResultOwnership as Ownership;
        use brokk_bifrost_core::analyzer::config::AnalyzerConfig;
        use brokk_bifrost_core::analyzer::model::Language;
        for (declaration, implementation, expected) in [
            ("pub struct Payload(pub &'static str);", "", Ownership::Move),
            (
                "pub enum Payload { Value(&'static str) }",
                "",
                Ownership::Move,
            ),
            (
                "pub struct Payload(pub &'static str);",
                "impl core::marker::Copy for crate::Payload {} impl core::clone::Clone for crate::Payload { fn clone(&self) -> Self { *self } }",
                Ownership::Unknown,
            ),
            (
                "#[derive(core::clone::Clone, core::marker::Copy)] pub struct Payload(pub &'static str);",
                "",
                Ownership::Copy,
            ),
        ] {
            let project = crate::inline_project::InlineTestProject::with_language(Language::Rust)
                .file("Cargo.toml", "[package]\nname=\"payload_ownership\"\nversion=\"0.1.0\"\nedition=\"2021\"\n")
                .file("src/lib.rs", format!("mod implementation; {declaration} pub fn subject(value: Payload) -> Payload {{ value }} impl Payload {{ pub fn self_return(self) -> Self {{ self }} pub fn mutating(mut self) -> bool {{ true }} pub fn borrowed(&self) {{}} }}"))
                .file("src/implementation.rs", implementation)
                .build();
            let workspace = project.workspace_analyzer(AnalyzerConfig {
                parallelism: Some(1),
                ..Default::default()
            });
            let cancellation = CancellationToken::default();
            let mut budget = SemanticBudget::default();
            let outcome = workspace
                .materialize_program_semantics(
                    &project.file("src/lib.rs"),
                    &mut SemanticRequest::new(&mut budget, &cancellation),
                )
                .unwrap();
            let artifact = outcome.available_value().unwrap();
            for name in ["subject", "self_return"] {
                let procedure = artifact
                    .procedures()
                    .iter()
                    .find(|procedure| {
                        procedure.locator().declaration().last_segment_name() == Some(name)
                    })
                    .unwrap();
                let handle = artifact.procedure_handle(procedure.id()).unwrap();
                let mut budget = SemanticBudget::default();
                let ownership = selected_call_result_ownership(
                    &workspace,
                    &handle,
                    &mut SemanticRequest::new(&mut budget, &cancellation),
                )
                .unwrap();
                assert_eq!(
                    ownership, expected,
                    "{name}: {declaration} / {implementation}"
                );
            }
            for (name, expected) in [
                ("self_return", expected),
                ("mutating", expected),
                ("borrowed", Ownership::Unknown),
            ] {
                let procedure = artifact
                    .procedures()
                    .iter()
                    .find(|p| p.locator().declaration().last_segment_name() == Some(name))
                    .unwrap();
                let callee = artifact.procedure_handle(procedure.id()).unwrap();
                let mut budget = SemanticBudget::default();
                assert_eq!(
                    selected_formal_ownership(
                        &workspace,
                        &callee,
                        ProcedurePortKind::Receiver,
                        &mut SemanticRequest::new(&mut budget, &cancellation)
                    )
                    .unwrap(),
                    expected,
                    "declared receiver type: {name}: {declaration} / {implementation}"
                );
            }
            if declaration == "pub struct Payload(pub &'static str);" && implementation.is_empty() {
                let file = project.file("src/implementation.rs");
                file.write("impl core::marker::Copy for crate::Payload {} impl core::clone::Clone for crate::Payload { fn clone(&self) -> Self { *self } }").unwrap();
                let updated = workspace.update(&std::collections::BTreeSet::from([file]));
                let mut refresh_budget = SemanticBudget::default();
                let refreshed = updated
                    .materialize_program_semantics(
                        &project.file("src/lib.rs"),
                        &mut SemanticRequest::new(&mut refresh_budget, &cancellation),
                    )
                    .unwrap();
                let current_artifact = refreshed.available_value().unwrap();
                let receiver = current_artifact
                    .procedures()
                    .iter()
                    .find(|p| p.locator().declaration().last_segment_name() == Some("self_return"))
                    .unwrap();
                let callee = current_artifact.procedure_handle(receiver.id()).unwrap();
                let mut budget = SemanticBudget::default();
                assert_eq!(
                    selected_formal_ownership(
                        &updated,
                        &callee,
                        ProcedurePortKind::Receiver,
                        &mut SemanticRequest::new(&mut budget, &cancellation)
                    )
                    .unwrap(),
                    Ownership::Unknown,
                    "a warm receiver proof must observe an other-file Copy implementation"
                );
            }
        }
        // Receiver syntax outside the supported owned impl declaration must
        // remain Unknown, independently of the caller's value arena.
        let project = crate::inline_project::InlineTestProject::with_language(Language::Rust)
            .file("Cargo.toml", "[package]\nname=\"receiver_boundaries\"\nversion=\"0.1.0\"\nedition=\"2021\"\n")
            .file("src/lib.rs", "mod declarations;")
            .file("src/declarations.rs", "pub struct Local; impl Local { pub fn borrowed_mut(&mut self) {} pub fn typed(self: Box<Self>) {} } pub trait DefaultMethod: Sized { fn default_move(self) -> Self { self } }")
            .build();
        let workspace = project.workspace_analyzer(AnalyzerConfig {
            parallelism: Some(1),
            ..Default::default()
        });
        let cancellation = CancellationToken::default();
        let mut budget = SemanticBudget::default();
        let outcome = workspace
            .materialize_program_semantics(
                &project.file("src/declarations.rs"),
                &mut SemanticRequest::new(&mut budget, &cancellation),
            )
            .unwrap();
        let artifact = outcome.available_value().unwrap();
        for name in ["borrowed_mut", "typed", "default_move"] {
            let procedure = artifact
                .procedures()
                .iter()
                .find(|p| p.locator().declaration().last_segment_name() == Some(name))
                .unwrap();
            let callee = artifact.procedure_handle(procedure.id()).unwrap();
            let mut budget = SemanticBudget::default();
            assert_eq!(
                selected_formal_ownership(
                    &workspace,
                    &callee,
                    ProcedurePortKind::Receiver,
                    &mut SemanticRequest::new(&mut budget, &cancellation)
                )
                .unwrap(),
                Ownership::Unknown,
                "{name}"
            );
        }
    }

    #[test]
    fn formal_identity_requires_the_same_bare_nongeneric_selected_type() {
        use brokk_bifrost_analysis::analyzer::languages::SelectedIdentityConversion as Conversion;
        use brokk_bifrost_analysis::analyzer::semantic::{CancellationToken, SemanticBudget};
        use brokk_bifrost_core::analyzer::config::AnalyzerConfig;
        use brokk_bifrost_core::analyzer::model::Language;

        let project = crate::inline_project::InlineTestProject::with_language(Language::Rust)
            .file("Cargo.toml", "[package]\nname = \"formal_identity\"\nversion = \"0.1.0\"\nedition = \"2024\"\n[lib]\npath = \"lib.rs\"\n")
            .file("lib.rs", "mod resource; mod source; mod same; mod different; mod generic; mod alias; mod reference; mod wrapper; mod copy;")
            .file("resource.rs", "pub struct Resource { pub payload: String } pub struct Other { pub payload: String } pub struct Generic<T> { pub payload: T } pub type Alias = Resource; #[derive(Clone,Copy)] pub struct CopyResource;")
            .file("source.rs", "use crate::resource::Resource; pub fn source(_r:Resource) {}")
            .file("same.rs", "use crate::resource::Resource; pub fn same(_r:Resource) {}")
            .file("different.rs", "use crate::resource::Other; pub fn different(_r:Other) {}")
            .file("generic.rs", "use crate::resource::Generic; pub fn generic(_r:Generic<u8>) {}")
            .file("alias.rs", "use crate::resource::Alias; pub fn alias(_r:Alias) {}")
            .file("reference.rs", "use crate::resource::Resource; pub fn reference(_r:&Resource) {}")
            .file("wrapper.rs", "use crate::resource::Resource; pub fn wrapper(_r:Box<Resource>) {}")
            .file("copy.rs", "use crate::resource::CopyResource; pub fn copy(_r:CopyResource) {}")
            .build();
        let workspace = project.workspace_analyzer(AnalyzerConfig::default());
        let cancellation = CancellationToken::default();
        let procedure = |path: &str| {
            let mut budget = SemanticBudget::default();
            let artifact = workspace
                .materialize_program_semantics(
                    &project.file(path),
                    &mut SemanticRequest::new(&mut budget, &cancellation),
                )
                .unwrap()
                .available_value()
                .cloned()
                .unwrap();
            let row = artifact
                .procedures()
                .iter()
                .find(|p| p.kind() == ProcedureKind::Function)
                .unwrap();
            artifact.procedure_handle(row.id()).unwrap()
        };
        let source = procedure("source.rs");
        for (path, expected) in [
            ("same.rs", Conversion::Identity),
            ("different.rs", Conversion::Unknown),
            ("generic.rs", Conversion::Unknown),
            ("alias.rs", Conversion::Unknown),
            ("reference.rs", Conversion::Unknown),
            ("wrapper.rs", Conversion::Unknown),
            ("copy.rs", Conversion::Unknown),
        ] {
            let target = procedure(path);
            let mut budget = SemanticBudget::default();
            assert_eq!(
                selected_formal_identity_conversion(
                    &workspace,
                    &source,
                    0,
                    &target,
                    0,
                    &mut SemanticRequest::new(&mut budget, &cancellation),
                )
                .unwrap(),
                expected,
                "{path}",
            );
        }
        let target = procedure("same.rs");
        let mut limits = SemanticBudget::default().limits();
        limits.nested_entries = 1;
        let mut tiny = SemanticBudget::new(limits).unwrap();
        assert_eq!(
            selected_formal_identity_conversion(
                &workspace,
                &source,
                0,
                &target,
                0,
                &mut SemanticRequest::new(&mut tiny, &cancellation),
            )
            .unwrap(),
            Conversion::Unknown,
        );
        assert!(tiny.refusal_count() > 0);
        let mut fresh = SemanticBudget::default();
        assert_eq!(
            selected_formal_identity_conversion(
                &workspace,
                &source,
                0,
                &target,
                0,
                &mut SemanticRequest::new(&mut fresh, &cancellation),
            )
            .unwrap(),
            Conversion::Identity,
        );
    }
}

