            let ends = procedure.logical_scope_ends().collect::<Vec<_>>();
            assert!(!ends.is_empty(), "{source}");
            assert!(
                ends.iter()
                    .all(|end| matches!(end.place, SemanticPlace::LocalBinding(_)))
            );
